using SmartMaint.Api.Entities.Accounts;
using SmartMaint.Api.Entities.Buildings;

namespace SmartMaint.Api.Entities.Cases;

/// <summary>
/// A maintenance case (ERD: Cases). Column names follow the D-plan (*_at, *_id); the ERD name is in the comment.
/// Columns marked NOT IN ERD v5 are listed in docs/database/ERD_v5_Thay_Doi_Khi_Code.md for the ERD meeting.
/// The display code CS-000123 is built from the id, not stored.
/// </summary>
public class Case : AuditableEntity
{
    /// <summary>ERD: RequestingCustomer. Empty for a case generated by preventive maintenance (F2).</summary>
    public long? RequestingCustomerId { get; set; }
    public Customer? Customer { get; set; }

    /// <summary>NOT IN ERD v5: where the problem is. The ERD only links Assets, but a customer may not know the asset.</summary>
    public long RoomId { get; set; }
    public Room Room { get; set; } = null!;

    public long? AssetId { get; set; }
    public Asset? Asset { get; set; }

    public long CategoryId { get; set; }
    public CaseCategory Category { get; set; } = null!;

    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;

    /// <summary>ERD: Status -> CaseStatuses.ID (column status_id).</summary>
    public CaseStatus Status { get; set; }

    public long PriorityLevelId { get; set; }
    public PriorityLevel Priority { get; set; } = null!;

    /// <summary>NOT IN ERD v5: who pays for the repair, set by the staff member on approval (N23).</summary>
    public CostBearer CostBearer { get; set; }

    /// <summary>The staff member who approved it (ERD: Staff). Any staff of the building may act; the first to approve is kept.</summary>
    public long? StaffId { get; set; }
    public Staff? Staff { get; set; }

    /// <summary>
    /// The technician holding it now (ERD: AssignedTechnician). Only the last one is kept; declines are in
    /// TechnicianRejections and who assigned whom is in the status history (Assigned rows).
    /// </summary>
    public long? AssignedTechnicianId { get; set; }
    public Technician? Technician { get; set; }

    /// <summary>ERD: TimeSubmitted.</summary>
    public DateTimeOffset SubmittedAt { get; set; }

    /// <summary>
    /// The SLA clock starts when the technician starts work (doc "Luồng Chính", 28/10). ERD: StartTime.
    /// DueAt (ERD: DueTime) = StartedAt + the priority's SlaHours. Both are cleared on Reopen and set again on the next start.
    /// </summary>
    public DateTimeOffset? StartedAt { get; set; }
    public DateTimeOffset? DueAt { get; set; }

    /// <summary>ERD: TimeCompleted.</summary>
    public DateTimeOffset? CompletedAt { get; set; }

    /// <summary>NOT IN ERD v5: needed for the 7-day "not fixed" window.</summary>
    public DateTimeOffset? ClosedAt { get; set; }

    /// <summary>ERD: EstimatedCompletionHours.</summary>
    public decimal? EstimatedCompletionHours { get; set; }

    /// <summary>ERD: ActualCompletionHours. Typed by the technician, or measured from StartedAt to CompletedAt.</summary>
    public decimal? ActualCompletionHours { get; set; }

    /// <summary>ERD: TimeOutsourced. This case has an outside party (F5); the moment of the hand-over.</summary>
    public DateTimeOffset? OutsourcedAt { get; set; }

    /// <summary>NOT IN ERD v5 (repair record). Parts are written by hand: there is no stock (N2).</summary>
    public string? RootCause { get; set; }
    public string? PartsUsed { get; set; }

    /// <summary>NOT IN ERD v5: filled while Status = OnHold.</summary>
    public HoldReason? HoldReason { get; set; }
    public DateOnly? HoldUntil { get; set; }

    /// <summary>NOT IN ERD v5: the customer's rating, once per case.</summary>
    public int? RatingStars { get; set; }
    public string? RatingComment { get; set; }
    public DateTimeOffset? RatedAt { get; set; }

    /// <summary>
    /// NOT IN ERD v5: the customer's "not fixed" report waiting for the staff member's answer (within 7 days of closing).
    /// Cleared when the staff member reopens the case or declines the report.
    /// </summary>
    public string? NotFixedReason { get; set; }
    public DateTimeOffset? NotFixedAt { get; set; }

    /// <summary>
    /// NOT IN ERD v5: when the SLA reminder job told the staff that the deadline is near / passed, so each reminder
    /// goes out once. Both are cleared when the deadline changes.
    /// </summary>
    public DateTimeOffset? SlaWarnedAt { get; set; }
    public DateTimeOffset? SlaOverdueNotifiedAt { get; set; }

    public List<CaseImage> Images { get; set; } = [];
    public List<CaseStatusHistory> History { get; set; } = [];
    public List<TechnicianRejection> Rejections { get; set; } = [];
    public List<Cost> Costs { get; set; } = [];

    public static string CodeOf(long id) => $"CS-{id:D6}";
}

/// <summary>ERD: CaseImages(ID, Image, Notes, Case). Kind (report / before / after) is NOT IN ERD v5.</summary>
public class CaseImage : AuditableEntity
{
    public long CaseId { get; set; }
    public Case Case { get; set; } = null!;
    public CaseImageKind Kind { get; set; }

    /// <summary>Path of the file in storage (Supabase Storage bucket, or the local folder in dev), not a URL.</summary>
    public string Image { get; set; } = string.Empty;

    public string? Notes { get; set; }
}

/// <summary>
/// One status change. ERD: CaseStatusHistory(ID, NewStatus, Case, TimeChanged). ChangedBy and Reason are NOT IN ERD v5:
/// without them nobody can tell who approved, closed or paused a case, or why. The previous status is the row before.
/// </summary>
public class CaseStatusHistory : Entity
{
    public long CaseId { get; set; }
    public Case Case { get; set; } = null!;

    /// <summary>ERD: NewStatus -> CaseStatuses.ID (column new_status_id).</summary>
    public CaseStatus NewStatus { get; set; }

    /// <summary>ERD: TimeChanged.</summary>
    public DateTimeOffset ChangedAt { get; set; }

    public long ChangedById { get; set; }
    public Account ChangedBy { get; set; } = null!;
    public string? Reason { get; set; }
}

/// <summary>
/// ERD: Costs(ID, Name, Description, Amount, Case) — one cost line of a repair: a part the technician bought, or the
/// labour line the system adds on "complete" (hours × the technician's HourlyRate, E9). Amount in VND.
/// </summary>
public class Cost : AuditableEntity
{
    public long CaseId { get; set; }
    public Case Case { get; set; } = null!;
    public string Name { get; set; } = string.Empty;
    public string? Description { get; set; }
    public decimal Amount { get; set; }
}

/// <summary>
/// ERD: TechnicianRejections(Technician, Case, RejectedTime, Reason) — a technician declined an assignment.
/// Key (CaseId, TechnicianId, RejectedAt): the same technician may decline the same case again after a reopen.
/// </summary>
public class TechnicianRejection
{
    public long TechnicianId { get; set; }
    public Technician Technician { get; set; } = null!;
    public long CaseId { get; set; }
    public Case Case { get; set; } = null!;

    /// <summary>ERD: RejectedTime.</summary>
    public DateTimeOffset RejectedAt { get; set; }

    public string Reason { get; set; } = string.Empty;
}
